//--- captures m^0, m^2 and m^4 parts of the coefficient and stores
//--- in a common block
void ggZZcapture(const std::string& label, int h34, int h56, int j1, int j2, int j3, int j4, int j5, int j6,
    std::complex<double>& amp0, std::complex<double>& amp2, std::complex<double>& amp4) {
  const int imt0 = 1, imt2 = 2, imt4 = 3;
  const int ipp = 1, imp = 2;
