    for (size_t l = 1; l <= res.nl; l++) {
      for (size_t k = 1; k <= res.nk; k++) {
        for (size_t j = 1; j <= res.nj; j++) {
          for (size_t i = 1; i <= res.ni; i++) {
            res(i, j, k, l) = czip;
          }
        }
      }
    }
    first = false;
  }

  htag = -1;

