      itag = c12_34;
    }
    if ((trimmed == "12x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c12_34;
    }
    if ((trimmed == "1x34x2mp") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d1_34_2;
    }
    if ((trimmed == "1x34x2pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d1_34_2;
    }
    if ((trimmed == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d2_1_34;
    }
    if ((trimmed == "2x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d2_1_34;
    }
    if ((trimmed == "d62x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d6_2_1_34;
    }
