      ltag = 2;
      itag = label[5] - '0';
    }
    if ((label.size() >= 6) && (label.compare(0, 5, "bubpp") == 0) && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 2;
      itag = label[5] - '0';
    }
  }

  //--- Permute 1 and 2:  2 1 3 4 5 6
  if ((j1 == 2) && (j2 == 1) && (j3 == 3) && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
    if ((trimmed == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimmed == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimmed == "2x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d1_2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimmed == "d62x1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 4;
      itag = d6_1_2_34;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
  }

  //--- Permute 3,4 and 5,6:  1 2 5 6 3 4
  if ((j1 == 1) && (j2 == 2) && (j3 == 5) && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
    if ((trimmed == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c1_56;
    }
    if ((trimmed == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c1_56;
    }
    if ((trimmed == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 4;
      itag = d1_2_34;
    }
  }

  //--- Permute 1,3,4 and 2,5,6:  2 1 3 4 5 6
  if ((j1 == 2) && (j2 == 1) && (j3 == 5) && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
    if ((trimmed == "1x34") && (h34 == 1) && (h56 == 1)) {
      htag = imp;
      ltag = 3;
      itag = c2_56;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
    if ((trimmed == "1x34pp") && (h34 == 1) && (h56 == 1)) {
      htag = ipp;
      ltag = 3;
      itag = c2_56;
      if (amp0 != czip) amp0 = std::conj(amp0);
      if (amp2 != czip) amp2 = std::conj(amp2);
      if (amp4 != czip) amp4 = std::conj(amp4);
    }
  }

  if (htag < 0) {
    return;
  }

  //--- assign results
  // @coverage-probe
  res(htag, ltag, itag, imt0) = amp0;
  res(htag, ltag, itag, imt2) = amp2;
  res(htag, ltag, itag, imt4) = amp4;

  if (std::abs(res(htag, ltag, itag, imt0)) < 1e-8) res(htag, ltag, itag, imt0) = czip;
  if (std::abs(res(htag, ltag, itag, imt2)) < 1e-8) res(htag, ltag, itag, imt2) = czip;
  if (std::abs(res(htag, ltag, itag, imt4)) < 1e-8) res(htag, ltag, itag, imt4) = czip;

  return;
}

