  void ggZZcapture_wrapper(const char* label, int h34, int h56, int j1, int j2, int j3, int j4, int j5, int j6,
      std::complex<double>& amp0, std::complex<double>& amp2, std::complex<double>& amp4) {
    std::string label_str(label);
